.eyebrow { font-family:'Avenir Next','Inter',sans-serif; color:#7E673F; font-size:.70em; letter-spacing:.15em; text-transform:uppercase; font-weight:700; border-top: 1px solid #DDCBAA; padding-top:.8em; margin:0 0 2em; }
.eyebrow p { margin:0; }
